127	            report_if_automatic(std::move(doing), std::move(error), std::move(stack));
128	        });
129	        return;
130	    }
131	    BOOST_LOG_TRIVIAL(error) << "Unexpected error while " << doing << ": " << error;
132	    if (reports_automatically()) {
133	        ErrorReport report = make_error_report(std::move(doing), std::move(error), {});
134	        report.stack = std::move(stack);
