269	// What an auth endpoint answered, in allauth's shapes: 200 once signed in,
270	// with the token in "meta"; 401 while a code is pending, with the session
271	// token to carry; 400 with "errors"; 409 once the pending code is gone. A
272	// token goes on to the same check as the browser's; a refusal the person can
273	// act on stays on the step; anything else ends the sign-in with one generic
274	// error.
275	std::optional<CloudSignInOutcome> CloudSignIn::answered(CloudHttpResult http)
276	{
277	    m_email.busy = false;
278	    const json body   = json::parse(http.body, nullptr, false);
279	    const auto errors = [&](const char* code) {
280	        if (!body.is_object() || !body.contains("errors") || !body["errors"].is_array())
281	            return false;
282	        return std::any_of(body["errors"].begin(), body["errors"].end(),
283	                           [code](const json& error) { return error.is_object() && error.value("code", "") == code; });
284	    };
285	    const std::string session = body.is_object() ? body.value("/meta/session_token"_json_pointer, std::string()) : std::string();
286	    const std::string token   = body.is_object() ? body.value("/meta/access_token"_json_pointer, std::string()) : std::string();
287	
288	    if (m_asked == "code/request" && http.status == 401 && !session.empty()) {
289	        m_email.code_resent = m_email.step == CloudEmailStep::Step::Code;
290	        m_email.step        = CloudEmailStep::Step::Code;
291	        m_session           = session;
292	        return std::nullopt;
293	    }
294	    if (http.status == 200 && !token.empty()) {
295	        m_session.clear();
296	        begin_check(token);
297	        return std::nullopt;
298	    }
299	    const std::string said = "JusPrin's sign-in answered " + m_asked + " with HTTP " + std::to_string(http.status) + ": " + http.body;
300	    if (const std::optional<AgentError> outdated = update_required(http.status, http.body))
301	        return failed(outdated->code, outdated->message, outdated->retryable, said);
302	    if (http.status == 400 && m_asked == "code/request" && errors("too_many_login_attempts"))
303	        m_email.refusal = "too_many_codes";
304	    else if (http.status == 400 && m_asked == "code/request" && errors("invalid"))
305	        // allauth's EmailField refuses an address the web view's own check
306	        // lets through, such as one with no dot after the @.
307	        m_email.refusal = "incomplete_address";
308	    else if (http.status == 400 && m_asked == "code/confirm" && errors("incorrect_code"))
309	        m_email.refusal = "wrong_code";
310	    else if (http.status == 409 && m_asked == "code/confirm")
311	        m_email.refusal = "expired_code";
312	    else if (http.status == 400 && m_asked == "login")
313	        m_email.refusal = errors("too_many_login_attempts") ? "too_many_tries" : "wrong_password";
314	    else if (http.status == 0 || (http.status >= 400 && http.status < 500))
315	        return failed("sign_in_failed", translated(L("JusPrin couldn't sign you in. Try again.")), true, said);
316	    else
317	        unexpected(said);
318	    // A refusal the person can act on, on the same step.
319	    BOOST_LOG_TRIVIAL(warning) << "JusPrin email sign-in refused, the person is told " << m_email.refusal << ": " << said;
320	    return std::nullopt;
321	}
