 63	// OrcaSlicer's OAuthJob, with its result handed on once it is final.
 64	class SignInJob final : public Job
 65	{
 66	public:
 67	    SignInJob(const CloudAuthorization& authorization, std::function<void(CloudAuthorizationResult)> done)
 68	        : m_result(std::make_shared<OAuthResult>()), m_done(std::move(done)),
 69	          m_job(OAuthData{OAuthParams{authorization.authorize_url, authorization.client_id, authorization.port,
 70	                                      authorization.redirect_uri, authorization.scope, "code", authorization.success_url,
 71	                                      authorization.failure_url, authorization.token_url, authorization.code_verifier,
 72	                                      authorization.state},
 73	                          m_result})
 74	    {
 75	        // OAuthJob tells this window it has finished; nothing listens there,
 76	        // because finalize() below is where its result is read.
 77	        m_job.set_event_handle(wxGetApp().mainframe);
 78	    }
 79	
 80	    // OAuthJob stops its loopback server in its own finalize(). That runs
 81	    // here, on the worker, so the port is free before a sign-in started
 82	    // right after a cancelled one opens it again; the worker would otherwise
 83	    // start the next job before the GUI thread got to finalize this one.
 84	    void process(Ctl& ctl) override
 85	    {
 86	        m_job.process(ctl);
 87	        std::exception_ptr none;
 88	        m_job.finalize(ctl.was_canceled(), none);
 89	    }
 90	
 91	    void finalize(bool canceled, std::exception_ptr& eptr) override
 92	    {
 93	        if (eptr) {
 94	            // Another program holding the loopback port is the one failure
 95	            // expected here; the person is told sign-in didn't finish and can
 96	            // try again. Anything else is a fault and goes on.
 97	            try {
 98	                std::rethrow_exception(eptr);
 99	            } catch (const boost::system::system_error& error) {
100	                BOOST_LOG_TRIVIAL(warning) << "JusPrin sign-in could not listen for the browser: " << error.what();
101	                eptr = nullptr;
102	                m_done({false, {}, error.what()});
103	            }
104	            return;
105	        }
106	        if (canceled)
107	            return;
108	        m_done({m_result->success, m_result->access_token, m_result->error_message});
109	    }
110	
111	private:
112	    std::shared_ptr<OAuthResult>                  m_result;
113	    std::function<void(CloudAuthorizationResult)> m_done;
114	    OAuthJob                                      m_job;
115	};
