119	CloudAccountDeps make_cloud_account_deps()
120	{
121	    // The worker is a thread of its own, started by the first sign-in: every
122	    // agent rebuild makes these dependencies, and most never sign in.
123	    auto worker = std::make_shared<std::unique_ptr<BoostThreadWorker>>();
124	
125	    CloudAccountDeps deps;
126	    deps.authorize = [worker](const CloudAuthorization& authorization, std::function<void(CloudAuthorizationResult)> done) {
127	        if (!*worker)
128	            *worker = std::make_unique<BoostThreadWorker>(std::make_shared<NoProgress>(), "jusprin_sign_in");
129	        if (!replace_job(**worker, std::make_unique<SignInJob>(authorization, std::move(done))))
130	            return false;
131	        wxLaunchDefaultBrowser(wxString::FromUTF8(authorization.authorize_url));
132	        return true;
133	    };
134	    deps.cancel_authorize = [worker] {
135	        if (*worker)
136	            (*worker)->cancel_all();
137	    };
138	    deps.pump = [worker] {
139	        if (*worker)
140	            (*worker)->process_events();
141	    };
142	    deps.get = [](const std::string& url, const std::string& token, std::function<void(CloudHttpResult)> done) {
143	        auto http = Slic3r::Http::get(url);
144	        http.header("Authorization", "Bearer " + token)
145	            .header("User-Agent", Updates::user_agent())
146	            .header("Accept", "application/json")
147	            .tls_verify(true)
148	            .timeout_connect(10)
149	            .timeout_max(30)
150	            .on_complete(reported("reading the JusPrin account", [done](std::string body, unsigned status) { done({status, std::move(body)}); }))
151	            .on_error(reported("reading the JusPrin account", [done](std::string body, std::string error, unsigned status) {
152	                BOOST_LOG_TRIVIAL(warning) << "JusPrin account request failed (" << status << "): " << error;
153	                done({status, std::move(body)});
154	            }))
155	            .perform();
156	    };
157	    deps.post = [](const std::string& url, const std::string& body, const std::string& session,
158	                   std::function<void(CloudHttpResult)> done) {
159	        auto http = Slic3r::Http::post(url);
160	        if (!session.empty())
161	            http.header("X-Session-Token", session);
162	        // The sign-in code email is written in this language.
163	        if (const std::string language = server_language(); !language.empty())
164	            http.header("Accept-Language", language);
165	        http.header("User-Agent", Updates::user_agent())
166	            .header("Content-Type", "application/json")
167	            .header("Accept", "application/json")
168	            .set_post_body(body)
169	            .tls_verify(true)
170	            .timeout_connect(10)
171	            .timeout_max(30)
172	            .on_complete(reported("signing in to JusPrin", [done](std::string body, unsigned status) { done({status, std::move(body)}); }))
173	            .on_error(reported("signing in to JusPrin", [done](std::string body, std::string error, unsigned status) {
174	                // A refusal (4xx) comes here too, with the server's body.
175	                if (status == 0)
176	                    BOOST_LOG_TRIVIAL(warning) << "JusPrin email sign-in request failed: " << error;
177	                done({status, std::move(body)});
178	            }))
179	            .perform();
180	    };
181	    deps.revoke = [](const std::string& url, const std::string& client_id, const std::string& token) {
182	        auto http = Slic3r::Http::post(url);
183	        http.header("User-Agent", Updates::user_agent())
184	            .form_add("token", token)
185	            .form_add("client_id", client_id)
186	            .timeout_connect(10)
187	            .timeout_max(30)
188	            .on_error(reported("signing out of JusPrin", [url](std::string body, std::string error, unsigned status) {
189	                // No answer, such as no network: the token is already
190	                // forgotten on this computer, and nobody can act on it.
191	                if (status == 0) {
192	                    BOOST_LOG_TRIVIAL(warning) << "Signing out of JusPrin reached no server at " << url << ": " << error;
193	                    return;
194	                }
195	                // Forgotten on this computer, the token still works on the
196	                // server.
197	                throw RuntimeError("revoking the token at " + url + " answered " + std::to_string(status) + ": " + error +
198	                                   (body.empty() ? std::string() : " " + body));
199	            }))
200	            .perform();
201	    };
202	    deps.pkce = [](std::string& verifier, std::string& challenge, std::string& state) {
203	        verifier = base64_url(random_bytes(32));
204	        unsigned char digest[SHA256_DIGEST_LENGTH];
205	        SHA256(reinterpret_cast<const unsigned char*>(verifier.data()), verifier.size(), digest);
206	        challenge = base64_url(std::string(reinterpret_cast<const char*>(digest), sizeof(digest)));
207	        state     = base64_url(random_bytes(16));
208	    };
209	    return deps;
210	}
