240	bool CloudSignIn::send_code()
241	{
242	    if (m_phase != CloudSignInPhase::Email || m_email.busy)
243	        return false;
244	    // A new request rather than allauth's resend: a resent code keeps the
245	    // first one's deadline and is refused once that code is spent. The
246	    // pending code's session stays until the new one's arrives, in case the
247	    // server refuses to send another.
248	    ask_server("code/request", {{"email", m_email.email}}, {});
249	    return true;
250	}
