261	{
262	    if (m_phase != CloudSignInPhase::Email || m_email.busy || m_email.step != CloudEmailStep::Step::Choose)
263	        return false;
264	    // The server signs in by username; allauth matches it against addresses too.
265	    ask_server("login", {{"username", m_email.email}, {"password", password}}, {});
266	    return true;
