323	void CloudSignIn::cancel()
324	{
325	    if (m_phase == CloudSignInPhase::Browser && m_deps.cancel_authorize)
326	        m_deps.cancel_authorize();
327	    ++m_generation;
328	    m_phase = CloudSignInPhase::Idle;
329	    m_token.clear();
330	    m_session.clear();
331	    m_who.reset();
332	    m_models.reset();
333	}
334	
335	std::optional<CloudSignInOutcome> CloudSignIn::poll()
336	{
337	    if (m_deps.pump)
338	        m_deps.pump();
339	    while (std::optional<Inbox::Item> item = m_inbox->pop()) {
340	        if (item->generation != m_generation)
341	            continue; // from a sign-in that was cancelled
342	        switch (item->kind) {
343	        case Inbox::Kind::Authorized:
344	            if (m_phase != CloudSignInPhase::Browser)
345	                continue;
346	            if (!item->authorization.ok || item->authorization.access_token.empty())
347	                return failed("sign_in_failed", translated(L("Signing in didn't finish. Nothing was saved. Try again.")), true,
348	                              "the browser sign-in ended " + (item->authorization.ok ? std::string("without a token") : item->authorization.error));
349	            begin_check(std::move(item->authorization.access_token));
350	            break;
351	        case Inbox::Kind::Auth:
352	            if (m_phase != CloudSignInPhase::Email)
353	                continue;
354	            if (std::optional<CloudSignInOutcome> outcome = answered(std::move(item->http)))
355	                return outcome;
356	            break;
357	        case Inbox::Kind::Who: m_who = std::move(item->http); break;
358	        case Inbox::Kind::Models: m_models = std::move(item->http); break;
359	        }
360	        if (m_phase == CloudSignInPhase::Checking && m_who && m_models)
361	            return finish_check();
362	    }
363	    return std::nullopt;
364	}
365	
366	std::optional<CloudSignInOutcome> CloudSignIn::finish_check()
367	{
368	    const CloudHttpResult who    = std::move(*m_who);
369	    const CloudHttpResult models = std::move(*m_models);
370	    m_who.reset();
371	    m_models.reset();
372	    if (refused(who) || refused(models)) {
373	        m_phase = CloudSignInPhase::Idle;
374	        m_token.clear();
375	        CloudSignInOutcome outcome;
376	        outcome.kind = CloudSignInOutcome::Kind::Expired;
377	        return outcome;
378	    }
379	    const std::string said = "JusPrin's account check answered HTTP " + std::to_string(who.status) + ", its model list HTTP " +
380	                             std::to_string(models.status) + ": " + models.body;
381	    if (const std::optional<AgentError> outdated = update_required(models.status, models.body))
382	        return failed(outdated->code, outdated->message, outdated->retryable, said);
383	    if (who.status == 0 || models.status == 0)
384	        return failed("account_unreachable", translated(L("JusPrin couldn't be reached to finish signing in. Try again.")), true, said);
385	    const json who_json    = json::parse(who.body, nullptr, false);
386	    const json models_json = json::parse(models.body, nullptr, false);
387	    if (who.status != 200 || models.status != 200 || !who_json.is_object() || !models_json.is_object() ||
388	        !models_json.contains("data"))
389	        unexpected("JusPrin's account check answered HTTP " + std::to_string(who.status) + ": " + who.body +
390	                   ", and its model list HTTP " + std::to_string(models.status) + ": " + models.body);
391	
392	    // /jusprin/api/me/ answers {"user": {"id", "email", ...}, "ai_credits": {...}}.
393	    const json account_id = who_json.value("/user/id"_json_pointer, json());
394	    if (!account_id.is_number_integer())
395	        unexpected("JusPrin's account check answered without the account's number: " + who.body);
396	
397	    CloudAccountRecord record;
398	    record.token      = m_token;
399	    record.email      = who_json.value("/user/email"_json_pointer, std::string());
400	    record.account_id = std::to_string(account_id.get<long long>());
401	    for (const json& entry : models_json["data"]) {
402	        const std::string id = entry.value("id", ""), format = entry.value("format", "");
403	        if (!id.empty() && !format.empty())
404	            record.formats.emplace_back(id, format);
405	    }
406	    // The agent is for the provider's default model, or else the first the
407	    // server lists.
408	    auto chosen = std::find_if(record.formats.begin(), record.formats.end(),
409	                               [this](const auto& entry) { return entry.first == m_default_model; });
410	    if (chosen == record.formats.end())
411	        chosen = record.formats.begin();
412	    AgentServicePtr service = chosen == record.formats.end() ? nullptr : m_agents(m_token, chosen->first, chosen->second);
413	    if (!service)
414	        return failed("account_no_models", translated(L("JusPrin has no AI model for this account right now. Try again later.")), true, said);
415	
416	    // Sign-in is over whether or not the account can be stored.
417	    m_phase = CloudSignInPhase::Idle;
418	    m_token.clear();
419	    m_store.save(record);
420	    CloudSignInOutcome outcome;
421	    outcome.kind    = CloudSignInOutcome::Kind::SignedIn;
422	    outcome.email   = record.email;
423	    outcome.service = std::move(service);
424	    return outcome;
425	}
