467	void CloudSignIn::sign_out()
468	{
469	    // Sign out is drawn only while signed in.
470	    const std::optional<CloudAccountRecord> record = account();
471	    if (!record)
472	        throw RuntimeError("jusprin-cloud-account: signing out with no account stored");
473	    if (!m_store.erase)
474	        throw std::logic_error("jusprin-cloud-account: signing out of a store that cannot forget an account");
475	    m_store.erase();
476	    cancel();
477	    if (m_deps.revoke)
478	        m_deps.revoke(m_server + "/o/revoke_token/", kCloudClientId, record->token);
479	}
