 32	std::string base64_url(const std::string& bytes)
 33	{
 34	    std::string text = base64_bytes(bytes);
 35	    std::replace(text.begin(), text.end(), '+', '-');
 36	    std::replace(text.begin(), text.end(), '/', '_');
 37	    text.erase(std::remove(text.begin(), text.end(), '='), text.end());
 38	    return text;
 39	}
 40	
 41	std::string random_bytes(std::size_t count)
 42	{
 43	    std::string bytes(count, '\0');
 44	    if (RAND_bytes(reinterpret_cast<unsigned char*>(bytes.data()), static_cast<int>(count)) != 1)
 45	        throw std::runtime_error("OpenSSL could not produce random bytes for a JusPrin sign-in");
 46	    return bytes;
 47	}
