119	CloudAccountDeps make_cloud_account_deps()
120	{
121	    // The worker is a thread of its own, started by the first sign-in: every
122	    // agent rebuild makes these dependencies, and most never sign in.
123	    auto worker = std::make_shared<std::unique_ptr<BoostThreadWorker>>();
124	
125	    CloudAccountDeps deps;
126	    deps.authorize = [worker](const CloudAuthorization& authorization, std::function<void(CloudAuthorizationResult)> done) {
127	        if (!*worker)
128	            *worker = std::make_unique<BoostThreadWorker>(std::make_shared<NoProgress>(), "jusprin_sign_in");
129	        if (!replace_job(**worker, std::make_unique<SignInJob>(authorization, std::move(done))))
130	            return false;
131	        wxLaunchDefaultBrowser(wxString::FromUTF8(authorization.authorize_url));
132	        return true;
133	    };
134	    deps.cancel_authorize = [worker] {
135	        if (*worker)
136	            (*worker)->cancel_all();
137	    };
138	    deps.pump = [worker] {
139	        if (*worker)
140	            (*worker)->process_events();
141	    };
142	    deps.get = [](const std::string& url, const std::string& token, std::function<void(CloudHttpResult)> done) {
143	        auto http = Slic3r::Http::get(url);
144	        http.header("Authorization", "Bearer " + token)
145	            .header("User-Agent", Updates::user_agent())
146	            .header("Accept", "application/json")
147	            .tls_verify(true)
148	            .timeout_connect(10)
149	            .timeout_max(30)
150	            .on_complete(reported("reading the JusPrin account", [done](std::string body, unsigned status) { done({status, std::move(body)}); }))
151	            .on_error(reported("reading the JusPrin account", [done](std::string body, std::string error, unsigned status) {
152	                BOOST_LOG_TRIVIAL(warning) << "JusPrin account request failed (" << status << "): " << error;
153	                done({status, std::move(body)});
154	            }))
155	            .perform();
156	    };
157	    deps.post = [](const std::string& url, const std::string& body, const std::string& session,
158	                   std::function<void(CloudHttpResult)> done) {
159	        auto http = Slic3r::Http::post(url);
160	        if (!session.empty())
